const s = params.wingspan;
const L = s * 0.72;
const r = s * 0.075;
const bodyY = s * 0.16;
const primary = params.color;
const cream = '#eee9dc';
const dark = '#252b31';
const silver = '#aeb6bd';
const glass = '#78a9bd';
const rubber = { preset: 'rubber', color: '#17191c', roughness: 0.92 };
const metal = { preset: 'metal', color: silver, metalness: 0.72, roughness: 0.3 };
const paint = { preset: 'metal', color: primary, metalness: 0.28, roughness: 0.38 };
const trim = { preset: 'metal', color: cream, metalness: 0.18, roughness: 0.42 };

const fuselage = api.capsule(r, L * 0.88).rotate(90, 0, 0).scale(1, 1, 1.04).translate(0, bodyY, 0);
fuselage.vertexColor((x, y, z) => y < bodyY - r * 0.18 ? api.mix(primary, dark, 0.18) : primary);
api.add(fuselage, { preset: 'metal', metalness: 0.3, roughness: 0.38 });
api.add(api.cylinder(r * 0.78, r * 0.96, r * 0.7, 16).rotate(90, 0, 0).translate(0, bodyY, L * 0.47), paint);
api.add(api.cylinder(r * 0.98, r * 0.98, r * 0.11, 16).rotate(90, 0, 0).translate(0, bodyY, L * 0.405), metal);

const wingShape = [[-s * 0.5, 0], [-s * 0.47, -L * 0.19], [-r * 0.8, -L * 0.07], [r * 0.8, -L * 0.07], [s * 0.47, -L * 0.19], [s * 0.5, 0], [r * 0.85, L * 0.12], [-r * 0.85, L * 0.12]];
const wing = api.extrude(wingShape, r * 0.16).rotate(90, 0, 0).translate(0, bodyY - r * 0.08, L * 0.02);
wing.vertexColor((x, y, z) => Math.abs(x) > s * 0.35 ? cream : primary);
api.add(wing, { preset: 'metal', metalness: 0.24, roughness: 0.4 });

const tailSpan = s * 0.34;
const tailShape = [[-tailSpan * 0.5, 0], [-tailSpan * 0.46, -L * 0.1], [tailSpan * 0.46, -L * 0.1], [tailSpan * 0.5, 0], [r * 0.35, L * 0.075], [-r * 0.35, L * 0.075]];
const stabilizer = api.extrude(tailShape, r * 0.1).rotate(90, 0, 0).translate(0, bodyY + r * 0.08, -L * 0.38);
stabilizer.vertexColor((x, y, z) => Math.abs(x) > tailSpan * 0.36 ? cream : primary);
api.add(stabilizer, { preset: 'metal', metalness: 0.24, roughness: 0.4 });

const finShape = [[-L * 0.085, 0], [L * 0.08, 0], [L * 0.025, r * 2.75], [-L * 0.06, r * 2.15]];
const fin = api.extrude(finShape, r * 0.16).translate(0, bodyY + r * 0.38, -L * 0.39);
fin.vertexColor((x, y, z) => y > bodyY + r * 2.25 ? cream : primary);
api.add(fin, { preset: 'metal', metalness: 0.24, roughness: 0.4 });

const canopy = api.sphere(r * 1.02, 2).scale(0.78, 0.54, 1.35).translate(0, bodyY + r * 0.78, L * 0.06);
api.add(canopy, { preset: 'glass', color: glass, opacity: 0.78, roughness: 0.12, metalness: 0.05 });
api.add(api.box(r * 0.09, r * 1.02, r * 1.55).rotate(24, 0, 0).translate(0, bodyY + r * 0.74, L * 0.055), { preset: 'metal', color: dark, metalness: 0.65, roughness: 0.25 });
api.add(api.box(r * 1.65, r * 0.1, r * 1.42).translate(0, bodyY + r * 0.73, L * 0.055), { preset: 'metal', color: dark, metalness: 0.65, roughness: 0.25 });

const hubZ = L * 0.535;
api.add(api.cylinder(r * 0.18, r * 0.18, r * 0.55, 12).rotate(90, 0, 0).translate(0, bodyY, hubZ - r * 0.16), metal);
api.add(api.sphere(r * 0.34, 2).scale(0.72, 0.72, 1).translate(0, bodyY, hubZ + r * 0.15), paint);
const bladeShape = [[-r * 0.1, 0], [-r * 0.18, r * 0.72], [-r * 0.08, r * 1.85], [r * 0.13, r * 1.9], [r * 0.18, r * 0.7], [r * 0.1, 0]];
for (let i = 0; i < 2; i++) {
  const blade = api.extrude(bladeShape, r * 0.07).rotate(0, 0, i * 180 + 18).translate(0, bodyY, hubZ + r * 0.29);
  blade.vertexColor((x, y, z) => Math.abs(y - bodyY) > r * 1.55 ? cream : dark);
  api.add(blade, { preset: 'metal', metalness: 0.55, roughness: 0.3 });
}

const gearY = bodyY - r * 1.25;
for (let side = -1; side <= 1; side += 2) {
  const gx = side * s * 0.16;
  api.add(api.cylinder(r * 0.07, r * 0.07, r * 1.55, 8).rotate(0, 0, side * -13).translate(gx * 0.86, bodyY - r * 0.72, L * 0.06), metal);
  api.add(api.cylinder(r * 0.34, r * 0.34, r * 0.18, 12).rotate(0, 0, 90).translate(gx, gearY, L * 0.06), rubber);
  api.add(api.cylinder(r * 0.13, r * 0.13, r * 0.2, 12).rotate(0, 0, 90).translate(gx, gearY, L * 0.06), metal);
}
api.add(api.cylinder(r * 0.055, r * 0.055, r * 0.75, 8).rotate(12, 0, 0).translate(0, bodyY - r * 0.65, -L * 0.39), metal);
api.add(api.cylinder(r * 0.2, r * 0.2, r * 0.12, 10).rotate(0, 0, 90).translate(0, bodyY - r * 1.02, -L * 0.43), rubber);

for (let side = -1; side <= 1; side += 2) {
  api.add(api.sphere(r * 0.18, 1).scale(1, 0.5, 0.55).translate(side * s * 0.47, bodyY - r * 0.02, L * 0.015), { preset: 'glass', color: side < 0 ? '#e33b32' : '#59d37d', emissive: side < 0 ? '#e33b32' : '#59d37d', emissiveIntensity: 1.5 });
}
api.add(api.box(r * 0.08, r * 0.65, r * 0.035).translate(0, bodyY, L * 0.485), trim);
api.collider({ kind: 'capsule', radius: r, halfHeight: L * 0.42, offset: [0, bodyY, 0], rotation: [90, 0, 0] });
api.collider({ kind: 'box', halfExtents: [s * 0.49, r * 0.09, L * 0.14], offset: [0, bodyY - r * 0.08, L * 0.01] });
api.collider({ kind: 'box', halfExtents: [tailSpan * 0.49, r * 0.07, L * 0.09], offset: [0, bodyY + r * 0.08, -L * 0.39] });
api.collider({ kind: 'box', halfExtents: [s * 0.2, r * 0.34, r * 0.26], offset: [0, gearY, L * 0.06] });
return api.build();
